"""Shared wording for the unit-6 explanations (explain_u6.py and explain_u6_e4 ... explain_u6_e8; the
semester-2 mock explanations import some of it through explain_u6). Steps starting with '## ' are stage
headings; every other step is numbered in the review."""

VEC = r"المتجه من النقطة $A$ إلى النقطة $B$: $\overrightarrow{AB}=B-A$ (إحداثيات النهاية ناقص إحداثيات البداية)"
MAG = r"مقدار المتجه $\langle a,b,c\rangle$ هو $\sqrt{a^2+b^2+c^2}$"
PAR = r"المتجهان متوازيان إذا كان أحدهما مضاعفًا للآخر: $\vec{\mathbf{u}}=k\vec{\mathbf{v}}$ لعدد حقيقي $k$"
LINE = r"المعادلة المتجهة للمستقيم: $\vec{\mathbf{r}}=\vec{\mathbf{r}}_0+t\vec{\mathbf{v}}$ ، حيث $\vec{\mathbf{r}}_0$ متجه موقع نقطة على المستقيم، و $\vec{\mathbf{v}}$ متجه اتجاهه"
REL = r"العلاقة بين مستقيمين: إذا توازى متجها الاتجاه فهما متوازيان أو منطبقان (نختبر نقطة من أحدهما على الآخر)، وإلّا فهما متقاطعان أو متخالفان (نحلّ معادلات تساوي الإحداثيات)"
DOT = r"الضرب القياسي: $\langle a_1,a_2,a_3\rangle\cdot\langle b_1,b_2,b_3\rangle=a_1b_1+a_2b_2+a_3b_3$ ، وأيضًا $\vec{\mathbf{u}}\cdot\vec{\mathbf{v}}=|\vec{\mathbf{u}}||\vec{\mathbf{v}}|\cos\theta$ ، والمتجهان متعامدان إذا كان ضربهما القياسي صفرًا"
UNIT = r"متجه الوحدة في اتجاه $\vec{\mathbf{v}}$ هو $\dfrac{\vec{\mathbf{v}}}{|\vec{\mathbf{v}}|}$ (نقسم كل مركبة على المقدار)، ومقداره دائمًا $1$"
MID = r"منتصف القطعة بين نقطتين = متوسط إحداثياتهما: $\left(\frac{x_1+x_2}{2},\frac{y_1+y_2}{2},\frac{z_1+z_2}{2}\right)$"
ANGLE = r"الزاوية بين متجهين: $\cos\theta=\dfrac{\vec{\mathbf{u}}\cdot\vec{\mathbf{v}}}{|\vec{\mathbf{u}}||\vec{\mathbf{v}}|}$ ، و $0\le\theta\le\pi$ (إشارة الضرب القياسي السالبة تعني زاوية منفرجة)"
PT = r"نقطة على المستقيم ← نكتب إحداثياتها العامة بدلالة $t$ ، ونستعمل المعلومة المعطاة لإيجاد $t$ ، ثم نعوّض في باقي الإحداثيات"
FOOT = r"مسقط العمود من $P$ على مستقيم هو النقطة $Q$ عليه التي تجعل $\overrightarrow{PQ}$ عموديًّا على متجه اتجاه المستقيم (ضربهما القياسي صفر)"
COLL = r"تقع ثلاث نقاط على استقامة واحدة إذا كان المتجهان المنطلقان من إحداها إلى الأخريين متوازيين (أحدهما مضاعف للآخر)"
REL4 = r"الحالات الأربع: متوازيان (اتجاهان متوازيان ولا نقطة مشتركة)، منطبقان (اتجاهان متوازيان ونقطة مشتركة)، متقاطعان (اتجاهان غير متوازيين ونقطة مشتركة)، متخالفان (اتجاهان غير متوازيين ولا نقطة مشتركة)"
IJK = r"المتجه $a\hat{i}+b\hat{j}+c\hat{k}$ هو نفسه $\langle a,\,b,\,c\rangle$ ؛ والمركبة الغائبة صفر (مثلًا $4\hat{j}-3\hat{k}=\langle 0,\,4,\,-3\rangle$)"
COMB = r"الجمع والطرح والضرب في عدد تتمّ مركبةً مركبة: $k\langle a_1,a_2,a_3\rangle\pm\langle b_1,b_2,b_3\rangle=\langle ka_1\pm b_1,\ ka_2\pm b_2,\ ka_3\pm b_3\rangle$"
SCALE = r"المتجه الذي مقداره $m$ في اتجاه $\vec{\mathbf{v}}$ هو $m\cdot\dfrac{\vec{\mathbf{v}}}{|\vec{\mathbf{v}}|}$ ، وفي عكس اتجاهه $-m\cdot\dfrac{\vec{\mathbf{v}}}{|\vec{\mathbf{v}}|}$"
SECT = r"إذا كانت $N$ على $\overline{TM}$ و $TN:NM=m:n$ ، فإنّ $\overrightarrow{TN}=\dfrac{m}{m+n}\overrightarrow{TM}$ و $N=T+\overrightarrow{TN}$"
BOX = r"قراءة متوازي المستطيلات: الرأس $O$ نقطة الأصل، والرؤوس على المحاور لها إحداثي واحد غير صفري، والرأس المقابل لـ $O$ إحداثياته الأبعاد الثلاثة؛ وكل رأس آخر نأخذ منه البعدين اللذين يمرّ بهما"
PLANE = r"المستويات الإحداثية: على المستوى $xy$ يكون $z=0$ ، وعلى $xz$ يكون $y=0$ ، وعلى $yz$ يكون $x=0$ (الإحداثي الغائب من اسم المستوى هو الصفر)"
RATIO = r"مسائل النسبة: نكتب كل متجه مطلوب مسارًا عبر أضلاع معلومة (قاعدة المثلث: $\overrightarrow{XZ}=\overrightarrow{XY}+\overrightarrow{YZ}$)، وفي متوازي الأضلاع الضلعان المتقابلان متجهان متساويان، ثم نقارن معاملات $\vec{\mathbf{a}}$ و $\vec{\mathbf{b}}$"
DIST = r"البُعد بين نقطة $P$ ومستقيم هو طول العمود $\overline{PF}$ ، حيث $F$ مسقط العمود من $P$ على المستقيم: $|\overrightarrow{PF}|$"
AREA = r"مساحة المثلث القائم تساوي $\frac12\times$ حاصل ضرب ضلعي القائمة، ونعرف الزاوية القائمة من الضرب القياسي: $\overrightarrow{BA}\cdot\overrightarrow{BC}=0$ يعني أن الزاوية $B$ قائمة"
SIGN = r"إشارة $\vec{\mathbf{u}}\cdot\vec{\mathbf{v}}=|\vec{\mathbf{u}}||\vec{\mathbf{v}}|\cos\theta$ هي إشارة $\cos\theta$: موجبة إذا كانت الزاوية حادّة، صفر إذا كانت قائمة، سالبة إذا كانت منفرجة"
